'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,usd,formText} from '@/lib/pilot';
import {reportMoney,type ReportCell} from '@/lib/report-export';
import {serviceComponents,blockerLabel,type ServiceCommand} from '@/lib/service-days';
import {feeBuckets,type FeeAmounts,taxBuckets,signedCents,validateForward,type ForwardPreview,type ForwardReceipt,type PendingForward,type ServiceAmounts,type TaxAmounts} from '@/lib/service-forward';
import {useServiceRequest,PendingServiceRequest} from '@/components/service-request';
export const pendingForwardHeaders=['Posting service date','Original service start','Original service end (exclusive)','Reservation','Adjustment reference','Accommodation correction USD','Tax correction USD','Property fee correction (category unallocated) USD','OTA fee correction USD','Other revenue correction USD','Combined tax correction USD','City tax correction USD','State tax correction USD','Lodging tax correction USD','Uncategorized tax correction USD','Total correction USD','Reason'];
export function pendingForwardRows(entries:PendingForward[]):ReportCell[][]{return entries.map(e=>[e.service_date,e.original_service_start,e.original_service_end,e.reservation_id,e.adjustment_id,...serviceComponents.map(([key])=>reportMoney(e.delta[key])),...taxBuckets.map(([key])=>reportMoney(e.tax_buckets[key])),reportMoney(e.total_minor),e.reason])}
export function PendingForwardList({entries,period=false}:{entries:PendingForward[];period?:boolean}){return <section className="pilot-forward-pending"><h3>Approved corrections awaiting close</h3><p>{period?'Current property approvals, across all dates. They are excluded from the selected closed-period totals.':'These signed corrections will post on the service date shown when that day closes.'} Corrections do not add occupied nights.</p>{entries.length?<div className="pilot-table-wrap"><table className="pilot-table"><thead><tr>{pendingForwardHeaders.map(h=><th scope="col" key={h}>{h}</th>)}</tr></thead><tbody>{pendingForwardRows(entries).map((row,i)=><tr key={entries[i].adjustment_id}>{row.map((v,j)=><td key={j}>{String(v??'—')}</td>)}</tr>)}</tbody></table></div>:<p>No approved corrections await close.</p>}</section>}
export function ForwardFeeBreakdown({allocated,target,delta}:{allocated?:FeeAmounts|null;target?:FeeAmounts|null;delta?:FeeAmounts|null}){return <section><h3>Property fee correction categories</h3>{delta?<><p>These categories are calculated from the recorded fee classifications and will be saved with the correction.</p><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th scope="col">Fee category</th>{allocated&&<th scope="col">Already allocated USD</th>}{target&&<th scope="col">Required resulting USD</th>}<th scope="col">Signed correction USD</th></tr></thead><tbody>{feeBuckets.map(([key,label])=><tr key={key}><th scope="row">{label}</th>{allocated&&<td>{usd(allocated[key])}</td>}{target&&<td>{usd(target[key])}</td>}<td>{usd(delta[key])}</td></tr>)}</tbody></table></div></>:<p>A named fee breakdown is unavailable for this record.</p>}</section>}
export function ServiceForwardPanel({actor,tenant,property,reservation,onBusyChange,onSaved}:{actor:string;tenant:string;property:string;reservation:string;onBusyChange:(busy:boolean)=>void;onSaved:()=>Promise<void>}){
 const [data,setData]=useState<ForwardPreview|null>(null),[readError,setReadError]=useState(''),[formError,setFormError]=useState(''),[notice,setNotice]=useState('');const alive=useRef(true),sequence=useRef(0);
 const request=useServiceRequest('iratepilot-pms-pending-service-forward:'+actor+':'+tenant+':'+property+':'+reservation,tenant,property,onBusyChange);
 async function refresh(){const seq=++sequence.current;setData(null);setReadError('');try{const value=await hotelRpc<ForwardPreview>('service_forward_preview',{p_tenant:tenant,p_property:property,p_reservation:reservation});if(alive.current&&sequence.current===seq)setData(value)}catch(e){if(alive.current&&sequence.current===seq)setReadError(e instanceof Error?e.message:'Unable to load current correction basis.')}}
 useEffect(()=>{alive.current=true;const seq=++sequence.current;hotelRpc<ForwardPreview>('service_forward_preview',{p_tenant:tenant,p_property:property,p_reservation:reservation}).then(value=>{if(alive.current&&sequence.current===seq)setData(value)}).catch(e=>{if(alive.current&&sequence.current===seq)setReadError(e instanceof Error?e.message:'Unable to load current correction basis.')});return()=>{alive.current=false}},[tenant,property,reservation]);
 async function save(command:ServiceCommand){await request.run<ForwardReceipt>(command,async result=>{setNotice('Correction approval confirmed for '+result.service_date+'. The current history below shows whether it has posted.');await refresh();await onSaved()},()=>{void refresh()})}
 return <><p>Reconcile changed charges on a completed, fully allocated stay. This creates a separate reporting correction and preserves original closed entries. Record actual charge changes in the folio first.</p><button className="secondary" disabled={request.busy||!!request.pending} onClick={()=>void refresh()}>Refresh correction basis</button>{(request.error||readError||formError)&&<div className="pilot-error" role="alert">{request.error||readError||formError}</div>}{notice&&<output className="pilot-notice">{notice}</output>}{request.pending?<PendingServiceRequest command={request.pending} busy={request.busy} onRetry={()=>void save(request.pending!)}/>:!data?<p>Load the current charge basis before reviewing a correction.</p>:<><h3>{data.guest_name??data.reservation_id}</h3><p>Original service span: {data.original_service_start??'Unavailable'} to {data.original_service_end??'Unavailable'} (end exclusive). Correction posting date: <b>{data.service_date??'Ledger not started'}</b> · {data.time_zone}.</p><p>Current {data.financial_basis==='folio_charges'?'folio charges':'booked charges'}: <b>{data.current_total_minor===null?'Unknown':usd(data.current_total_minor)}</b>. Required signed correction: <b>{data.required_total_delta===null?'Unknown':usd(data.required_total_delta)}</b>.</p>{data.blockers.length>0&&<div className="pilot-error"><ul>{data.blockers.map(b=><li key={b}>{blockerLabel(b)}</li>)}</ul></div>}{data.eligible&&<form key={data.preview_hash} onSubmit={e=>{e.preventDefault();setFormError('');const f=new FormData(e.currentTarget);try{const delta=Object.fromEntries(serviceComponents.map(([key])=>[key,signedCents(f.get('delta_'+key))])) as ServiceAmounts,taxes=Object.fromEntries(taxBuckets.map(([key])=>[key,signedCents(f.get('tax_'+key))])) as TaxAmounts;validateForward(data,delta,taxes);void save({rpc:'approve_service_forward',label:'Approve reporting correction for reservation '+reservation+' on '+data.service_date,params:{p_request:crypto.randomUUID(),p_reservation:reservation,p_expected_book_version:data.book_version,p_expected_source_version:data.source_version,p_expected_pricing_hash:data.pricing_hash,p_expected_preview_hash:data.preview_hash,p_delta:delta,p_tax_buckets:taxes,p_reason:formText(f,'reason').trim()}})}catch(e){setFormError(e instanceof Error?e.message:'Review signed correction amounts.')}}}><p>{data.component_totals_fixed?'The resulting components must match the required totals below.':'Classify the signed correction using the actual folio adjustment evidence. Positive amounts add to reported allocations; negative amounts reduce them.'} Previously approved corrections are already included in the allocated amounts.</p><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th scope="col">Component</th><th scope="col">Already allocated USD</th>{data.component_totals_fixed&&<th scope="col">Required resulting USD</th>}<th scope="col">Signed correction USD</th></tr></thead><tbody>{serviceComponents.map(([key,label])=><tr key={key}><th scope="row">{label}</th><td>{usd(data.allocated_components[key])}</td>{data.component_totals_fixed&&<td>{usd(data.target_components[key])}</td>}<td><label className="sr-only" htmlFor={'delta_'+key}>{label} correction USD</label><input id={'delta_'+key} name={'delta_'+key} type="number" step="0.01" min="-9999999999.99" max="9999999999.99" required defaultValue={reportMoney(data.suggested_delta?.[key]??0)} disabled={request.busy||request.blocked}/></td></tr>)}</tbody></table></div><h3>Tax correction categories</h3><p>These categories must sum to the tax correction. When recorded tax targets are available, each resulting category must match its target. Use Uncategorized only for an unspecified aggregate.</p><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th scope="col">Tax category</th><th scope="col">Already allocated USD</th>{data.target_tax_buckets&&<th scope="col">Required resulting USD</th>}<th scope="col">Signed correction USD</th></tr></thead><tbody>{taxBuckets.map(([key,label])=><tr key={key}><th scope="row">{label}</th><td>{usd(data.allocated_tax_buckets[key])}</td>{data.target_tax_buckets&&<td>{usd(data.target_tax_buckets[key])}</td>}<td><label className="sr-only" htmlFor={'tax_'+key}>{label} correction USD</label><input id={'tax_'+key} name={'tax_'+key} type="number" step="0.01" min="-9999999999.99" max="9999999999.99" required defaultValue={reportMoney(data.suggested_tax_delta?.[key]??0)} disabled={request.busy||request.blocked}/></td></tr>)}</tbody></table></div><ForwardFeeBreakdown allocated={data.allocated_fee_buckets} target={data.target_fee_buckets} delta={data.suggested_fee_delta}/><label className="field">Correction reason<textarea name="reason" required minLength={4} maxLength={500} disabled={request.busy}/></label><label className="pilot-check"><input type="checkbox" required disabled={request.busy}/>I reviewed the source charges, signed components, tax categories, fee categories and posting date.</label><button className="primary" disabled={request.busy||request.blocked}>Approve forward correction</button></form>}<h3>Previous correction approvals</h3>{data.prior_adjustments.length?<div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th scope="col">Posting date</th><th scope="col">State</th><th scope="col">Reference</th><th scope="col">Correction USD</th><th scope="col">Fee breakdown</th><th scope="col">Reason</th></tr></thead><tbody>{data.prior_adjustments.map(a=><tr key={a.adjustment_id}><td>{a.service_date}</td><td>{a.posted?'Posted':'Awaiting close'}</td><td>{a.adjustment_id}</td><td>{usd(serviceComponents.reduce((n,[k])=>n+a.delta[k],0))}</td><td><details><summary>View fee categories</summary><ForwardFeeBreakdown delta={a.fee_buckets}/></details></td><td>{a.reason}</td></tr>)}</tbody></table></div>:<p>No previous correction approvals.</p>}</>}</>;
}
